import{c as a,Q as t,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const A=JSON.parse('{"title":"GetReduceAnyMaxMinTmpSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetReduceAnyMaxMinTmpSize","slug":"getreduceanymaxmintmpsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/归约操作/ReduceAny接口/GetReduceAnyMaxMinTmpSize.md","filePath":"api/SIMD-API/高阶API/归约操作/ReduceAny接口/GetReduceAnyMaxMinTmpSize.md"}'),d={name:"api/SIMD-API/高阶API/归约操作/ReduceAny接口/GetReduceAnyMaxMinTmpSize.md"};function i(l,e,r,p,c,u){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="getreduceanymaxmintmpsize" tabindex="-1">GetReduceAnyMaxMinTmpSize <a class="header-anchor" href="#getreduceanymaxmintmpsize" aria-label="Permalink to &quot;GetReduceAnyMaxMinTmpSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>kernel侧ReduceAny接口的计算需要开发者预留/申请临时空间，本接口用于在host侧获取预留/申请的最大最小临时空间大小，开发者基于此范围选择合适的空间大小作为Tiling参数传递到kernel侧使用。</p><ul><li>为保证功能正确，预留/申请的临时空间大小不能小于最小临时空间大小。</li><li>在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。该接口<strong>最大临时空间当前等于最小临时空间</strong>。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetReduceAnyMaxMinTmpSize(const ge::Shape&amp; srcShape, const ge::DataType dataType, ReducePattern pattern, bool isSrcInnerPad, bool isReuseSource, uint32_t&amp; maxValue, uint32_t&amp; minValue)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数列表</p><table tabindex="0"><thead><tr><th>接口</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入的shape信息，参数取值与ReduceAny接口的srcShape参数保持一致。</td></tr><tr><td>dataType</td><td>输入</td><td>输入的数据类型，ge::DataType类型，当前支持的数据类型与ReduceAny接口的模板参数T保持一致。</td></tr><tr><td>pattern</td><td>输入</td><td>用于指定ReduceAny的计算轴。ReducePattern类型，该类型的定义如下，包括Reduce轴和Normal轴。pattern由与输入向量维度数量相同的A、R字母组合形成，字母A表示Normal轴，R表示Reduce轴。该参数的取值与ReduceAny接口的pattern参数保持一致，当前只支持取值为AscendC::ReducePattern::AR，AscendC::ReducePattern::RA。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen710911418164&quot;&gt;enum class ReducePattern : uint32_t { AR = 0, RA = 1, R, ARA, ARAR, ARARA, ARARAR, ARARARA, ARARARAR, ARARARARA, RAR, RARA, RARAR, RARARA, RARARAR, RARARARA, };&lt;/pre&gt;</td></tr><tr><td>isSrcInnerPad</td><td>输入</td><td>表示实际需要计算的最内层轴数据是否32Bytes对齐，参数取值与ReduceAny接口的isSrcInnerPad参数保持一致。</td></tr><tr><td>isReuseSource</td><td>输入</td><td>是否复用源操作数输入的空间，参数取值与ReduceAny接口的isReuseSource参数保持一致。</td></tr><tr><td>maxValue</td><td>输出</td><td>ReduceAny接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。 说明： maxValue仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minValue</td><td>输出</td><td>ReduceAny接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的调用样例请参考<a href="./../../数学计算/更多样例-83.html">更多样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 输入shape为16*32的矩阵;算子输入的数据类型为float;不允许修改源操作数</span></span>
<span class="line"><span>auto shape = ge::Shape({ 16, 32 });</span></span>
<span class="line"><span>uint32_t maxValue = 0;</span></span>
<span class="line"><span>uint32_t minValue = 0;</span></span>
<span class="line"><span>bool isSrcInnerPad = true;</span></span>
<span class="line"><span>bool isReuseSource = false;</span></span>
<span class="line"><span>AscendC::GetReduceAnyMaxMinTmpSize(shape, ge::DataType::DT_FLOAT, AscendC::ReducePattern::AR, isSrcInnerPad, isReuseSource, maxValue, minValue);</span></span></code></pre></div>`,16)])])}const R=a(d,[["render",i]]);export{A as __pageData,R as default};
